  - {name: P101_SpeedCmd, source: P101, table: holding, address: 2101, format: int16, scale: 0.01, writable: true, rewrite: 1s}
  - {name: P102_Running, source: P102, table: holding, address: 2000, format: bit:0}
  - {name: P102_Status, source: P102, table: holding, address: 2000, format: uint16}
  - {name: P102_VfdFault, source: P102, table: holding, address: 2000, format: bit:3}
