sim.st:
PROGRAM WetWell
(* Bench-only plant: WW-101 (level from an inflow/outflow balance, via
   lib/physics.st's WetWellModel) and two submersible-pump/VFD models
   (VfdModel). Inflow is InflowGpm plus a slow sinusoid (+-20 %) so the
   level never sits dead flat; InflowGpm set to 950 is the "storm" the
   design calls out. A real deployment deletes this task entirely —
   field.yaml has no sim task and points the same control programs at
   the real devices instead (see docs/design/examples-dogfood.md for the
   one place the field tag names needed a small glue program). *)
VAR_EXTERNAL
    LIT101_Level : REAL;
    LSHH101      : BOOL;
    LSLL101      : BOOL;
    FIT101_Flow  : REAL;
    SimDtS       : REAL;
    InflowGpm    : REAL;
    ForceLSHH    : BOOL;

    P101_RunCmd      : BOOL;
    P101_SpeedCmd    : REAL;
    P101_Running     : BOOL;
    P101_SpeedHz     : REAL;
    P101_Amps        : REAL;
    P101_VfdFault    : BOOL;
    P101_InjectFault : BOOL;
    P101_SealFail        : BOOL;
    P101_InjectSealFail  : BOOL;
    P101_OverTemp        : BOOL;
    P101_InjectOverTemp  : BOOL;

    P102_RunCmd      : BOOL;
    P102_SpeedCmd    : REAL;
    P102_Running     : BOOL;
    P102_SpeedHz     : REAL;
    P102_Amps        : REAL;
    P102_VfdFault    : BOOL;
    P102_InjectFault : BOOL;
    P102_SealFail        : BOOL;
    P102_InjectSealFail  : BOOL;
    P102_OverTemp        : BOOL;
    P102_InjectOverTemp  : BOOL;
END_VAR
VAR
    well   : WetWellModel;
    vfd101 : VfdModel;
    vfd102 : VfdModel;
    tSec   : REAL;
END_VAR
VAR CONSTANT
    InflowVaryFrac : REAL := 0.20;
    InflowPeriodS  : REAL := 240.0;
    TwoPi          : REAL := 6.2831853;
END_VAR

tSec := tSec + SimDtS;

vfd101(RunCmd := P101_RunCmd, SpeedCmd := P101_SpeedCmd, Dt := SimDtS, InjectFault := P101_InjectFault,
       Running => P101_Running, SpeedHz => P101_SpeedHz, Amps => P101_Amps, Fault => P101_VfdFault);
vfd102(RunCmd := P102_RunCmd, SpeedCmd := P102_SpeedCmd, Dt := SimDtS, InjectFault := P102_InjectFault,
       Running => P102_Running, SpeedHz => P102_SpeedHz, Amps => P102_Amps, Fault => P102_VfdFault);

(* Seal-leak and over-temp probes have no physics to speak of: pass the
   bench inject tags straight through, exactly like a wire from a switch. *)
P101_SealFail := P101_InjectSealFail;
P101_OverTemp := P101_InjectOverTemp;
P102_SealFail := P102_InjectSealFail;
P102_OverTemp := P102_InjectOverTemp;

FIT101_Flow := PumpFlowGpm(P101_SpeedHz) + PumpFlowGpm(P102_SpeedHz);

well(InflowGpm := InflowGpm * (1.0 + InflowVaryFrac * SIN(tSec / InflowPeriodS * TwoPi)),
     OutflowGpm := FIT101_Flow, Dt := SimDtS, Level := LIT101_Level);

(* The floats switch with a differential, as a real tilt float does: it
   trips at one level and resets a few inches past it, so a level sitting
   on the mark doesn't make it chatter. *)
IF ForceLSHH THEN
    LSHH101 := TRUE;
ELSIF LIT101_Level >= 95.0 THEN
    LSHH101 := TRUE;
ELSIF LIT101_Level <= 91.0 THEN
    LSHH101 := FALSE;
END_IF;
IF LIT101_Level <= 8.0 THEN
    LSLL101 := TRUE;
ELSIF LIT101_Level >= 12.0 THEN
    LSLL101 := FALSE;
END_IF;
END_PROGRAM

permissives.ld:
PROGRAM Permissives
(* HOA, interlocks, the high-high override, and fail-to-run — everything
   that turns a "please run" request from the sequence into an actual
   RunCmd, or refuses to. Open the diagram: right-click -> "Open With ->
   Ladder Diagram". *)
VAR_EXTERNAL
    LeadIsP101 : BOOL;
    LeadReq    : BOOL;
    LagReq     : BOOL;
    LSHH101    : BOOL;
    LSLL101    : BOOL;
    LIT101_Level : REAL;
    LeadOffLevel : REAL;
    DryRunHold   : BOOL;

    P101_Req       : BOOL;
    P101_SealFail  : BOOL;
    P101_OverTemp  : BOOL;
    P101_VfdFault  : BOOL;
    P101_Permissive: BOOL;
    P101_Mode      : INT;
    P101_Running   : BOOL;
    P101_RunCmd    : BOOL;
    P101_InHand    : BOOL;
    P101_FailToRun : BOOL;
    P101_LockedOut : BOOL;
    P101_Avail     : BOOL;

    P102_Req       : BOOL;
    P102_SealFail  : BOOL;
    P102_OverTemp  : BOOL;
    P102_VfdFault  : BOOL;
    P102_Permissive: BOOL;
    P102_Mode      : INT;
    P102_Running   : BOOL;
    P102_RunCmd    : BOOL;
    P102_InHand    : BOOL;
    P102_FailToRun : BOOL;
    P102_LockedOut : BOOL;
    P102_Avail     : BOOL;

    ResetFaults : BOOL;
    BothUnavail : BOOL;
    LeadFailed  : BOOL;
    P101_DutyOk : BOOL;
    P102_DutyOk : BOOL;
    LeadUnavail : BOOL;
END_VAR
VAR
    m101 : MotorStarter;
    m102 : MotorStarter;
END_VAR
LD
  // duty mapping + high-high override, one rung: LSHH forces the call
  // regardless of the sequence or who's lead
  RUNG p101req
    [ LeadIsP101 LeadReq | /LeadIsP101 LagReq | LSHH101 ] ( P101_Req )

  RUNG p102req (* the same duty mapping for P-102: called when it is lead, or as lag *)
    [ /LeadIsP101 LeadReq | LeadIsP101 LagReq | LSHH101 ] ( P102_Req )

  // dry-run protection: a low-low trip holds both pumps off, in Hand as
  // well as Auto, until the well has refilled to Lead off. Restarting the
  // moment the float clears would run a pump dry, stop it and start it
  // again every few seconds.
  RUNG dryhold (* the low-low float latches the hold *)
    LSLL101 ( S DryRunHold )

  RUNG dryrelease (* refilled to Lead off, the float clear: the pumps may run again *)
    GE(LIT101_Level, LeadOffLevel) /LSLL101 ( R DryRunHold )

  RUNG p101perm (* a dry well (the hold) blocks both pumps, not just the lead *)
    /P101_SealFail /P101_OverTemp /P101_VfdFault /DryRunHold ( P101_Permissive )

  RUNG p102perm (* the same trips as P-101, against P-102's own devices *)
    /P102_SealFail /P102_OverTemp /P102_VfdFault /DryRunHold ( P102_Permissive )

  // every BOOL input bound by name: no free input for rung power, so the
  // call sits alone on the rail — see docs/functions.md "Power pins in ladder"
  RUNG p101start
    m101:MotorStarter(Mode := P101_Mode, AutoReq := P101_Req, Permissive := P101_Permissive,
                       RunFb := P101_Running, Reset := ResetFaults,
                       Run => P101_RunCmd, InHand => P101_InHand, FailToRun => P101_FailToRun,
                       LockedOut => P101_LockedOut)

  RUNG p102start (* P-102's starter: the same block, a second instance *)
    m102:MotorStarter(Mode := P102_Mode, AutoReq := P102_Req, Permissive := P102_Permissive,
                       RunFb := P102_Running, Reset := ResetFaults,
                       Run => P102_RunCmd, InHand => P102_InHand, FailToRun => P102_FailToRun,
                       LockedOut => P102_LockedOut)

  RUNG p101avail (* Off (Mode 0) is never available, same as a failed, locked-out, or blocked pump *)
    /P101_FailToRun /P101_LockedOut P101_Permissive /EQ(P101_Mode, 0) ( P101_Avail )

  RUNG p102avail (* as p101avail, for P-102 *)
    /P102_FailToRun /P102_LockedOut P102_Permissive /EQ(P102_Mode, 0) ( P102_Avail )

  RUNG bothunavail (* neither pump can take a call: the station alarm *)
    /P101_Avail /P102_Avail ( BothUnavail )

  RUNG leadfailed (* whichever pump is currently lead, reflected for the sequence *)
    [ LeadIsP101 P101_FailToRun | /LeadIsP101 P102_FailToRun ] ( LeadFailed )

  // Fit to be lead: in Auto (the sequence commands it) and available. A
  // pump in Hand runs on the operator's say-so, so it is not.
  RUNG p101duty
    EQ(P101_Mode, 2) P101_Avail ( P101_DutyOk )

  RUNG p102duty (* as p101duty, for P-102 *)
    EQ(P102_Mode, 2) P102_Avail ( P102_DutyOk )

  RUNG leadunavail (* the lead is no longer fit while the other is: hand it over *)
    [ LeadIsP101 /P101_DutyOk P102_DutyOk | /LeadIsP101 /P102_DutyOk P101_DutyOk ] ( LeadUnavail )
END_LD
END_PROGRAM

level.fbd:
PROGRAM LevelControl
(* LIC-101: wet-well level to pump speed, plus the high level alarm
   seal-in. Open the diagram: right-click -> "Open With -> FBD Diagram". *)
VAR_EXTERNAL
    LIT101_Level   : REAL;
    LevelSP        : REAL;
    Kp             : REAL;
    Ki             : REAL;
    Kd             : REAL;
    MinSpeedHz     : REAL;
    MaxSpeedHz     : REAL;
    LevelDtS       : REAL;
    LeadReq        : BOOL;
    SpeedRef       : REAL;
    HighLevelAlmSP : REAL;
    HighLevelAlm   : BOOL;

    P101_RunCmd   : BOOL;
    P101_InHand   : BOOL;
    P101_SpeedCmd : REAL;
    P101_HandSpeedHz : REAL;
    P102_RunCmd   : BOOL;
    P102_InHand   : BOOL;
    P102_SpeedCmd : REAL;
    P102_HandSpeedHz : REAL;
END_VAR
FBD
  NETWORK 'LIC-101: level to pump speed'
  // AUTO free-wheels (CV tracks CV_MAN, bumpless on return) whenever no
  // pump is called — LeadReq false parks the loop instead of integrating
  // error for a pump that isn't running. Direct acting: level above
  // setpoint calls for MORE speed.
  lic : PID(AUTO := LeadReq, PV := LIT101_Level, SP := LevelSP,
            KP := Kp, KI := Ki, KD := Kd,
            CV_MIN := MinSpeedHz, CV_MAX := MaxSpeedHz,
            DIRECT := TRUE, DT := LevelDtS)
  SpeedRef := lic.CV

  NETWORK 'P-101 / P-102: speed commands'
  // stopped -> 0 Hz; running in Auto -> the loop's output; running in
  // Hand -> that pump's own hand-speed setpoint.
  P101_SpeedCmd := SEL(P101_RunCmd, 0.0, SEL(P101_InHand, SpeedRef, P101_HandSpeedHz))
  P102_SpeedCmd := SEL(P102_RunCmd, 0.0, SEL(P102_InHand, SpeedRef, P102_HandSpeedHz))

  NETWORK 'LAH-101: high level alarm'
  // seal-in with hysteresis — latches at HighLevelAlmSP, clears 5 % below
  // it, so a level sitting right on the setpoint doesn't chatter the alarm
  // on and off every scan.
  above = GE(LIT101_Level, HighLevelAlmSP)
  below = LE(LIT101_Level, SUB(HighLevelAlmSP, 5.0))
  HighLevelAlm := AND(OR(above, HighLevelAlm), NOT below)
END_FBD
END_PROGRAM

nautilus.yaml:
# lift-station — the bench build: a duplex sewage lift station on the
# loopback driver, with the plant itself simulated in ST (sim.st) so the
# whole thing runs, cycles, and alarms with nothing wired up. See
# field.yaml for the same control programs pointed at real VFDs and
# remote I/O over Modbus instead.
#
#   naut check .                validate offline
#   naut test  .                the acceptance suite (lift-station_test.yaml)
#   naut run   .                dashboard + tag API on http://localhost:8080
#   naut build .                one deployable controller binary
#
# Five tasks, four IEC languages, one tag store:
#   sequence.sfc     duty/standby sequencing — who's called, lead/lag,
#                    post-run, failover
#   level.fbd        the level->speed PID and the high-level alarm
#   permissives.ld   HOA, interlocks, the high-high override, fail-to-run
#   stats.st         runtime hours/starts, the flow totalizer
#   sim.st           bench only: the wet well and two pump/VFD models
#
# The operator screen (hmi/, served from server.hmi once built) carries the
# P&ID mimic (lift-station.mimic.json) and, at /3d, the same station in
# 3D (lift-station.scene.json); `naut check` holds both files to the tags.
name: lift-station

server:
  addr: "localhost:8080"
  online-edits: true
  # The operator screen, once built (cd hmi && npm run build). Tolerates
  # being absent — `naut check` and `naut run` don't fail before the first
  # `npm run build`, a request against a missing build just 404s — see the
  # README's "The operator screen" section. Serves it at "/"; the built-in
  # dashboard moves to "/_nautilus/".
  hmi: hmi/build

retain:
  file: retain.json   # operator setpoints + HOA modes survive a restart

# tags/station.yaml holds every operator setpoint and computed-state tag
# that's byte-identical between this manifest and field.yaml — the
# tags: list below keeps only what's bench-specific: the process values
# owned by the sim task (LIT101_Level, LSHH101, LSLL101, FIT101_Flow, the
# VFD feedback/command tags, the seal/over-temp probes), the bench-only
# fault/float injection tags, and InflowGpm.
tag-files:
  - tags/station.yaml

tasks:
  - program: sequence.sfc   # the first task is always the runtime's "main"
                            # task, whatever it's called here — naming it
                            # (a name: key) is a no-op `naut check` warns on
    scan: 250ms
  - name: level
    program: level.fbd
    scan: 100ms
    dt-tag: LevelDtS
  - name: permissives
    program: permissives.ld
    scan: 100ms
  - name: stats
    program: stats.st
    scan: 1s
    dt-tag: StatsDtS
  - name: sim
    program: sim.st
    scan: 100ms
    dt-tag: SimDtS

tags:
  # Process values — owned by the sim task here; field.yaml makes these
  # role: input (or a field-mapped role: state — see field.yaml) and lets
  # the Modbus driver supply them instead.
  - { name: LIT101_Level, role: state, init: 20.0, unit: "%", desc: "Wet-well level (LIT-101)" }
  - { name: LSHH101,      role: state, init: false, desc: "High-high float (LSHH-101)" }
  - { name: LSLL101,      role: state, init: false, desc: "Low-low float (LSLL-101)" }
  - { name: FIT101_Flow,  role: state, init: 0.0, unit: "gpm", desc: "Discharge flow (FIT-101)" }
  - { name: P101_Running, role: state, init: false, desc: "P-101 VFD running feedback" }
  - { name: P102_Running, role: state, init: false, desc: "P-102 VFD running feedback" }
  - { name: P101_VfdFault, role: state, init: false, desc: "P-101 VFD fault" }
  - { name: P102_VfdFault, role: state, init: false, desc: "P-102 VFD fault" }
  - { name: P101_SpeedHz, role: state, init: 0.0, unit: "Hz", desc: "P-101 VFD speed feedback" }
  - { name: P102_SpeedHz, role: state, init: 0.0, unit: "Hz", desc: "P-102 VFD speed feedback" }
  - { name: P101_Amps, role: state, init: 0.0, unit: "A", desc: "P-101 motor current" }
  - { name: P102_Amps, role: state, init: 0.0, unit: "A", desc: "P-102 motor current" }
  - { name: P101_SealFail, role: state, init: false, desc: "P-101 seal-leak probe" }
  - { name: P102_SealFail, role: state, init: false, desc: "P-102 seal-leak probe" }
  - { name: P101_OverTemp, role: state, init: false, desc: "P-101 motor over-temperature" }
  - { name: P102_OverTemp, role: state, init: false, desc: "P-102 motor over-temperature" }

  # Commands — sent to the VFDs (loopback here; the Modbus manifest in
  # field.yaml).
  - { name: P101_RunCmd, role: output, init: false, desc: "P-101 run command" }
  - { name: P102_RunCmd, role: output, init: false, desc: "P-102 run command" }
  - { name: P101_SpeedCmd, role: output, init: 0.0, unit: "Hz", desc: "P-101 speed command" }
  - { name: P102_SpeedCmd, role: output, init: 0.0, unit: "Hz", desc: "P-102 speed command" }

  # Bench-only setpoint (tags/station.yaml has the rest — every other
  # operator setpoint is byte-identical to field.yaml's).
  - { name: InflowGpm, role: setpoint, init: 190.0, unit: "gpm", desc: "Bench only: base inflow (a storm is 640)" }

  # Bench-only fault/float injection — nothing to wire up, just tags to
  # POST from the dashboard or the API.
  - { name: P101_InjectFault, role: setpoint, init: false, desc: "Bench only: trip P-101's VFD fault" }
  - { name: P101_InjectSealFail, role: setpoint, init: false, desc: "Bench only: trip P-101's seal-leak probe" }
  - { name: P101_InjectOverTemp, role: setpoint, init: false, desc: "Bench only: trip P-101's over-temperature contact" }
  - { name: P102_InjectFault, role: setpoint, init: false, desc: "Bench only: trip P-102's VFD fault" }
  - { name: P102_InjectSealFail, role: setpoint, init: false, desc: "Bench only: trip P-102's seal-leak probe" }
  - { name: P102_InjectOverTemp, role: setpoint, init: false, desc: "Bench only: trip P-102's over-temperature contact" }
  - { name: ForceLSHH, role: setpoint, init: false, desc: "Bench only: force the high-high float regardless of level" }

  # Computed state lives in tags/station.yaml — identical to field.yaml's.

alarms:
  defaults: { ack-required: true, auto-clear: true, shelve: true }
  shelve-times: [15m, 1h, 4h]
  journal: { keep: 500 }
  defs:
    - { id: LSHH101, tag: LSHH101, name: "Wet-well high-high (LSHH-101)", priority: critical, on-delay: 2s, class: process }
    - { id: HighLevel, tag: HighLevelAlm, name: "Wet-well high level (LIT-101)", priority: high, on-delay: 10s, class: process }
    - { id: LSLL101, tag: LSLL101, name: "Wet-well low-low (LSLL-101)", priority: medium, on-delay: 5s, class: process }
    - { id: P101_FailToRun, tag: P101_FailToRun, name: "P-101 failed to run", priority: high, class: equipment }
    - { id: P102_FailToRun, tag: P102_FailToRun, name: "P-102 failed to run", priority: high, class: equipment }
    - { id: P101_LockedOut, tag: P101_LockedOut, name: "P-101 locked out (3 fail-to-run trips)", priority: high, class: equipment }
    - { id: P102_LockedOut, tag: P102_LockedOut, name: "P-102 locked out (3 fail-to-run trips)", priority: high, class: equipment }
    - { id: P101_VfdFault, tag: P101_VfdFault, name: "P-101 VFD fault", priority: high, on-delay: 1s, class: equipment }
    - { id: P102_VfdFault, tag: P102_VfdFault, name: "P-102 VFD fault", priority: high, on-delay: 1s, class: equipment }
    - { id: P101_SealFail, tag: P101_SealFail, name: "P-101 seal-leak probe", priority: medium, on-delay: 5s, class: equipment }
    - { id: P102_SealFail, tag: P102_SealFail, name: "P-102 seal-leak probe", priority: medium, on-delay: 5s, class: equipment }
    - { id: P101_OverTemp, tag: P101_OverTemp, name: "P-101 motor over-temperature", priority: high, on-delay: 2s, class: equipment }
    - { id: P102_OverTemp, tag: P102_OverTemp, name: "P-102 motor over-temperature", priority: high, on-delay: 2s, class: equipment }
    - { id: BothUnavail, tag: BothUnavail, name: "Both pumps unavailable", priority: critical, on-delay: 5s, class: equipment }

driver:
  type: memory

sequence.sfc:
PROGRAM PumpSequence
(* Duty/standby sequencing: which pump(s) are called, who's lead, the
   post-run pump-down, and failover on a fail-to-run or a lead that is no
   longer fit to lead. Who leads: LeadSelect, applied while idle (0
   alternates after each pump-down, 1 and 2 hold P-101 or P-102), and
   never a pump that is not in Auto and available while the other is. Level and float
   logic only — the fault sensing, permissives and the actual RunCmd/
   SpeedCmd outputs live in permissives.ld and level.fbd; this program
   only ever asks for a pump ("LeadReq"/"LagReq"), never commands one
   directly. Open the diagram: right-click -> "Open With -> SFC Diagram". *)
VAR_EXTERNAL
    LIT101_Level : REAL;
    LSLL101      : BOOL;
    LeadOnLevel  : REAL;
    LagOnLevel   : REAL;
    LagOffLevel  : REAL;
    LeadOffLevel : REAL;
    PostRunSec   : REAL;
    LeadFailed   : BOOL; (* the lead pump's FailToRun, from permissives.ld *)
    LeadUnavail  : BOOL; (* the lead stopped being fit to lead, the other is (permissives.ld) *)
    LeadSelect   : INT;  (* 0 alternate, 1 P-101 lead, 2 P-102 lead *)
    P101_DutyOk  : BOOL;
    P102_DutyOk  : BOOL;
    LeadReq      : BOOL;
    LagReq       : BOOL;
    LeadIsP101   : BOOL;
    CycleCount   : INT;
    SeqStep      : STRING;
END_VAR
VAR
    postRunTmr : TON;
END_VAR
SFC

  INITIAL_STEP Idle:
    R  LeadReq;
    R  LagReq;
    N  SetIdle;
    N  PickLead;         (* who takes the next call *)
  END_STEP

  STEP Lead:
    S  LeadReq;
    R  LagReq;           (* dropping back from Lag: the lag pump stands down *)
    N  SetLead;
    P1 CountCycle;      (* one new cycle counted per lead call *)
    P1 PickLead;        (* the selection again as each call starts, in case
                           it changed since Idle; a pump unfit to lead is
                           never picked back (PickLead's second rule) *)
  END_STEP

  STEP Lag:
    S  LagReq;           (* LeadReq is already set; now both pumps are called *)
    N  SetLag;
  END_STEP

  STEP PostRun:
    N  RunDownTmr;        (* ACTION: pump-down timer, PT from PostRunSec *)
    N  SetPostRun;
  END_STEP

  STEP Alternate:
    P0 SwapDuty;           (* on deactivation, not activation: the pump
                              already draining the well keeps running for
                              the whole post-run — only the NEXT call goes
                              to the other pump (LeadIsP101 := NOT LeadIsP101) *)
    (* No N action here: PostRun and Alternate are active together, and
       both writing SeqStep in the same scan made the value depend on
       action-execution order — see docs/design/examples-dogfood.md.
       PostRun's own SetPostRun action already covers SeqStep for the
       whole pump-down; Alternate only swaps the duty pointer. *)
  END_STEP

  STEP Failover:
    P1 SwapDuty;            (* hand the lead call to the other pump *)
    N  SetFailover;
  END_STEP

  (* --- transitions --- *)

  TRANSITION t_call FROM Idle TO Lead := LIT101_Level >= LeadOnLevel AND NOT LSLL101;
  END_TRANSITION

  (* alternative divergence out of Lead: priority by declaration order *)
  TRANSITION t_failover FROM Lead TO Failover := LeadFailed OR LeadUnavail;
  END_TRANSITION
  TRANSITION t_lag FROM Lead TO Lag := LIT101_Level >= LagOnLevel;
  END_TRANSITION
  TRANSITION t_done FROM Lead TO (PostRun, Alternate) := LIT101_Level <= LeadOffLevel OR LSLL101;
  END_TRANSITION

  TRANSITION t_drop FROM Lag TO Lead := LIT101_Level <= LagOffLevel;
  END_TRANSITION

  TRANSITION t_resume FROM Failover TO Lead := TRUE; (* one scan, then straight back in *)
  END_TRANSITION

  (* simultaneous convergence: fires only once BOTH branches are done *)
  TRANSITION t_idle FROM (PostRun, Alternate) TO Idle := postRunTmr.Q;
  END_TRANSITION

  (* --- action blocks --- *)

  ACTION CountCycle:
    CycleCount := CycleCount + 1;
  END_ACTION

  ACTION SwapDuty:
    LeadIsP101 := NOT LeadIsP101;
  END_ACTION

  ACTION PickLead:
    (* The operator's choice first; alternation is Alternate's swap. *)
    IF LeadSelect = 1 THEN
      LeadIsP101 := TRUE;
    ELSIF LeadSelect = 2 THEN
      LeadIsP101 := FALSE;
    END_IF;
    (* Then never a lead that cannot take the call when the other can. *)
    IF LeadIsP101 AND NOT P101_DutyOk AND P102_DutyOk THEN
      LeadIsP101 := FALSE;
    ELSIF NOT LeadIsP101 AND NOT P102_DutyOk AND P101_DutyOk THEN
      LeadIsP101 := TRUE;
    END_IF;
  END_ACTION

  ACTION RunDownTmr:
    postRunTmr(IN := PostRun.X, PT := REAL_TO_TIME(PostRunSec * 1000.0));
  END_ACTION

  ACTION SetIdle:
    SeqStep := 'Idle';
  END_ACTION

  ACTION SetLead:
    SeqStep := 'Lead';
  END_ACTION

  ACTION SetLag:
    SeqStep := 'Lag';
  END_ACTION

  ACTION SetPostRun:
    SeqStep := 'PostRun';
  END_ACTION

  ACTION SetFailover:
    SeqStep := 'Failover';
  END_ACTION

END_SFC
END_PROGRAM

stats.st:
PROGRAM Stats
(* Runtime hours/starts for each pump (RuntimeMeter, lib/pump.st) and the
   station flow totalizer. Shared, unchanged, between the bench and field
   manifests — it only reads process values and writes rollups, never a
   role that differs between them. *)
VAR_EXTERNAL
    P101_Running : BOOL;
    P102_Running : BOOL;
    P101_Stats   : PumpStats;
    P102_Stats   : PumpStats;
    FIT101_Flow  : REAL;
    StationFlowGal: REAL;
    StatsDtS     : REAL;
END_VAR
VAR
    meter101 : RuntimeMeter;
    meter102 : RuntimeMeter;
END_VAR
meter101(Running := P101_Running, Dt := StatsDtS, Stats := P101_Stats);
meter102(Running := P102_Running, Dt := StatsDtS, Stats := P102_Stats);

(* Totalized discharge volume, gal: gal/min * s / 60. *)
StationFlowGal := StationFlowGal + FIT101_Flow * StatsDtS / 60.0;
END_PROGRAM

devices.yaml:
# The device map for the field deployment of this plant — the ONE
# hand-written input to `naut modbus import`. Two generic device types: a
# submersible-pump VFD (used for both P-101 and P-102) and a remote-I/O
# rack carrying the wet-well instruments and the pump-skid contacts. The
# schema is documented in modbus/codegen/devicemap.go.
#
# Regenerate the committed files with:
#   naut modbus import --map devices.yaml
#
# The importer names every tag `<instance id>_<register tag>`, with no way
# to suppress the prefix (modbus/codegen/devicemap.go). That's exact for
# both VFDs (id P101/P102 + Running/VfdFault/SpeedHz/Amps/RunCmd/SpeedCmd
# reproduces the tag model's names precisely), but the RIO instance's
# points can't land on their bare canonical names (LIT101_Level, LSHH101,
# ...) that way — see field_map.st, the one field-only program that
# renames RIO_* onto them, and docs/design/examples-dogfood.md for the
# finding.
#
# RunCmd is a writable single bit of the VFD's control word: the driver
# read-modify-writes it (modbus/driver.go), so it never disturbs any other
# bit a real drive's control word might carry.
devices:
  vfd:
    description: submersible pump VFD
    registers:
      - {tag: Status,   address: 2000, desc: "status word"}
      - {tag: Running,  address: 2000, format: "bit:0", desc: "running bit of the status word"}
      - {tag: VfdFault, address: 2000, format: "bit:3", desc: "fault bit of the status word"}
      - {tag: SpeedHz,  address: 2001, format: int16, scale: 0.01, unit: Hz, desc: "actual speed"}
      - {tag: Amps,     address: 2002, format: int16, scale: 0.1, unit: A, desc: "motor current"}
      - {tag: RunCmd,   address: 2100, format: "bit:0", writable: true, init: false, desc: "run command — control word bit 0"}
      - {tag: SpeedCmd, address: 2101, format: int16, scale: 0.01, writable: true, rewrite: 1s, init: 0.0, unit: Hz, desc: "speed command"}
  rio:
    description: remote I/O — wet-well instruments and pump-skid contacts
    registers:
      - {tag: Level,         address: 0, table: input, format: int16, scale: 0.01, unit: "%", desc: "wet-well level"}
      - {tag: Flow,          address: 1, table: input, format: int16, scale: 0.1, unit: "gpm", desc: "force-main discharge flow"}
      - {tag: LSHH101,       address: 0, table: discrete, desc: "high-high float"}
      - {tag: LSLL101,       address: 1, table: discrete, desc: "low-low float"}
      - {tag: P101_SealFail, address: 2, table: discrete, desc: "P101 seal-leak probe"}
      - {tag: P101_OverTemp, address: 3, table: discrete, desc: "P101 motor over-temperature"}
      - {tag: P102_SealFail, address: 4, table: discrete, desc: "P102 seal-leak probe"}
      - {tag: P102_OverTemp, address: 5, table: discrete, desc: "P102 motor over-temperature"}
instances:
  - {id: P101, type: vfd, host: 192.168.20.11, unit-id: 1, desc: "P-101 VFD"}
  - {id: P102, type: vfd, host: 192.168.20.12, unit-id: 2, desc: "P-102 VFD"}
  - {id: RIO,  type: rio, host: 192.168.20.20, unit-id: 3, desc: "wet-well remote I/O"}

lib/pump.st:
(* Runtime accounting shared by both pumps: a retained UDT (PumpStats) and
   a FUNCTION_BLOCK that updates it by reference, so neither the sequence
   nor the permissives ever touch accumulation math themselves. A .st file
   with no PROGRAM is a project library — see docs/functions.md "A .ld
   library" (the same rule, one language over). *)

TYPE
  PumpStats : STRUCT
    Starts     : INT;   (* start count *)
    Hours      : REAL;  (* run hours *)
    LastRunSec : REAL;  (* length of the most recently completed run *)
  END_STRUCT;
END_TYPE

FUNCTION_BLOCK RuntimeMeter
(* Counts a start on Running's rising edge, accumulates run hours while
   Running, and captures the length of the run that just ended. Bound to
   the UDT tag by VAR_IN_OUT so two calls (P101_Stats, P102_Stats) each
   read and write their own copy — see docs/functions.md "VAR_IN_OUT is a
   reference pin". *)
VAR_INPUT
    Running : BOOL;
    Dt      : REAL; (* seconds since the last call *)
END_VAR
VAR_IN_OUT
    Stats : PumpStats;
END_VAR
VAR
    edgeUp   : R_TRIG;
    edgeDown : F_TRIG;
    runSec   : REAL;
END_VAR
edgeUp(CLK := Running);
edgeDown(CLK := Running);
IF edgeUp.Q THEN
    Stats.Starts := Stats.Starts + 1;
    runSec := 0.0;
END_IF;
IF Running THEN
    Stats.Hours := Stats.Hours + Dt / 3600.0;
    runSec := runSec + Dt;
END_IF;
IF edgeDown.Q THEN
    Stats.LastRunSec := runSec;
END_IF;
END_FUNCTION_BLOCK

FUNCTION PumpFlowGpm : REAL
(* Discharge flow at a given VFD speed — a rough affinity curve pinned to
   two points: ~0 gpm below 25 Hz (not enough head to open the check
   valve), 400 gpm at 60 Hz, linear between. Shared by the bench sim
   (lib/physics.st) and anywhere logic wants an expected flow from a
   commanded speed. *)
VAR_INPUT
    SpeedHz : REAL;
END_VAR
IF SpeedHz <= 25.0 THEN
    PumpFlowGpm := 0.0;
ELSE
    PumpFlowGpm := (SpeedHz - 25.0) / (60.0 - 25.0) * 400.0;
END_IF;
END_FUNCTION

tags/station.yaml:
# Hand-authored tag file (not generated — contrast tags/modbus.yaml,
# which `naut modbus import` writes). Holds the tags that are byte-
# identical between the bench manifest (nautilus.yaml) and the field
# manifest (field.yaml): operator setpoints, and every computed-state tag
# the control programs derive themselves, regardless of which build
# supplies the process values underneath them. See each manifest's own
# `tags:` comment for what stays inline instead (process values,
# bench-only inject tags, InflowGpm) and why.
#
# Compose it into a project with:  tag-files: [tags/station.yaml]

# Operator setpoints — retained (retain.file in both manifests).
- { name: LeadOnLevel, role: setpoint, init: 60.0, unit: "%", desc: "Lead pump call" }
- { name: LagOnLevel, role: setpoint, init: 80.0, unit: "%", desc: "Lag pump call" }
