- { name: LevelSP, role: setpoint, init: 45.0, unit: "%", desc: "Level PID setpoint (pump speed loop)" }
- { name: Kp, role: setpoint, init: 2.0, desc: "Level PID proportional gain" }
- { name: Ki, role: setpoint, init: 0.05, unit: "1/s", desc: "Level PID integral gain" }
