- { name: LagReq, role: state, init: false, desc: "Sequence: lag pump called" }
- { name: SpeedRef, role: state, init: 0.0, unit: "Hz", desc: "Level PID output" }
- { name: P101_Req, role: state, init: false, desc: "P-101 called, after duty mapping" }
- { name: P102_Req, role: state, init: false, desc: "P-102 called, after duty mapping" }
- { name: P101_Permissive, role: state, init: false, desc: "P-101 permissive to run" }
- { name: P102_Permissive, role: state, init: false, desc: "P-102 permissive to run" }
- { name: P101_InHand, role: state, init: false, desc: "P-101 in Hand mode" }
- { name: P102_InHand, role: state, init: false, desc: "P-102 in Hand mode" }
- { name: P101_FailToRun, role: state, init: false, desc: "P-101 commanded but never confirmed running" }
- { name: P102_FailToRun, role: state, init: false, desc: "P-102 commanded but never confirmed running" }
- { name: P101_LockedOut, role: state, init: false, desc: "P-101 locked out after three fail-to-run trips" }
- { name: P102_LockedOut, role: state, init: false, desc: "P-102 locked out after three fail-to-run trips" }
- { name: P101_Avail, role: state, init: false, desc: "P-101 available (not failed, not locked out, permissive, not Off)" }
- { name: P102_Avail, role: state, init: false, desc: "P-102 available (not failed, not locked out, permissive, not Off)" }
- { name: BothUnavail, role: state, init: false, desc: "Neither pump is available" }
