- { name: P101_DutyOk, role: state, init: false, desc: "P-101 fit to be lead: in Auto and available" }
- { name: P102_DutyOk, role: state, init: false, desc: "P-102 fit to be lead: in Auto and available" }
- { name: LeadUnavail, role: state, init: false, desc: "The lead pump stopped being fit to lead while the other is" }
- { name: DryRunHold, role: state, init: false, desc: "Dry-run protection: low-low tripped, pumps held off until the well refills to Lead off" }
- { name: LeadFailed, role: state, init: false, desc: "The lead (on-duty) pump's fail-to-run" }
- { name: HighLevelAlm, role: state, init: false, desc: "High level alarm (LIT-101, latched with hysteresis)" }
- { name: P101_Stats, role: state, type: PumpStats, init: { Starts: 0, Hours: 0.0, LastRunSec: 0.0 }, desc: "P-101 runtime stats" }
